<?php
namespace App\Http\Controllers;
use App\Models\Service; use App\Support\Workspace; use Illuminate\Http\Request;
class ServiceController extends Controller { public function index(Request $request) { $business=Workspace::business($request); return view('services.index',['business'=>$business,'services'=>$business->services()->with('extras')->orderBy('name')->get()]); } public function store(Request $request) { $b=Workspace::business($request); $data=$request->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','duration_minutes'=>'required|integer|min:15|max:1440','base_price'=>'required|numeric|min:0']); $b->services()->create($data); return back()->with('status','Service added.'); } public function update(Request $request,Service $service) { $b=Workspace::business($request); Workspace::assertBusiness($service,$b); $data=$request->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','duration_minutes'=>'required|integer|min:15|max:1440','base_price'=>'required|numeric|min:0']); $service->update($data+['active'=>$request->boolean('active')]); return back()->with('status','Service updated.'); } }
